//! Detached Attr factories retain genuine owner and document-specific case.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}


#[test]
fn template_document_owner_kind_default_metadata_and_reuse_follow_actual_source(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var html=document.implementation.createHTMLDocument('html'),xml=document.implementation.createDocument(null,''),other=document.implementation.createDocument(null,''),ns='http://www.w3.org/1999/xhtml',mainHost=document.createElement('template'),htmlHost=html.createElement('template'),xmlHost=xml.createElementNS(ns,'template'),otherHost=other.createElementNS(ns,'template'),owners=[mainHost.content.ownerDocument,htmlHost.content.ownerDocument,xmlHost.content.ownerDocument,otherHost.content.ownerDocument];for(var i=0;i<owners.length;i++){var owner=owners[i],source=i===0?document:i===1?html:i===2?xml:other;if(owner===source||!(owner instanceof Document)||owner instanceof XMLDocument||owner.defaultView!==null||owner.ownerDocument!==null||owner.URL!=='about:blank'||owner.documentURI!=='about:blank'||owner.baseURI!=='about:blank'||owner.contentType!=='application/xml'||owner.compatMode!=='CSS1Compat'||owner.characterSet!=='UTF-8'||owner.documentElement!==null||owner.doctype!==null)throw 'real generic template document defaults';for(var j=0;j<i;j++)if(owner===owners[j])throw 'one distinct associated owner per source document';var nested=owner.createElementNS(ns,'template');if(nested.content.ownerDocument!==owner||nested.content!==nested.content)throw 'algorithm-created owner reuses itself';var sibling=source.createElementNS(ns,'template');if(sibling.content.ownerDocument!==owner)throw 'source document reuses associated owner';}
"#);
}
#[test]
fn template_document_owner_xml_kind_controls_factories_names_case_and_cdata_independently_of_mime(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var ns='http://www.w3.org/1999/xhtml',xml=document.implementation.createDocument(null,''),host=xml.createElementNS(ns,'template'),owner=host.content.ownerDocument,element=owner.createElement('MiXeD'),attr=owner.createAttribute('MiXeD'),cdata=owner.createCDATASection('\ud800'),htmlElement=owner.createElementNS(ns,'DiV');if(element.localName!=='MiXeD'||element.tagName!=='MiXeD'||element.namespaceURI!==null||element.ownerDocument!==owner||attr.name!=='MiXeD'||attr.ownerDocument!==owner||cdata.nodeType!==4||cdata.data.charCodeAt(0)!==0xd800||cdata.ownerDocument!==owner||htmlElement.tagName!=='DiV')throw 'XML template owner keeps actual document kind';htmlElement.setAttribute('MiXeD','case');if(htmlElement.getAttribute('MiXeD')!=='case'||htmlElement.getAttribute('mixed')!==null)throw 'XML owner attribute lookup is case sensitive';var htmlOwner=document.createElement('template').content.ownerDocument,htmlNode=htmlOwner.createElement('MiXeD'),htmlAttr=htmlOwner.createAttribute('MiXeD'),caught=false;try{htmlOwner.createCDATASection('x');}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||htmlOwner.contentType!==owner.contentType||htmlNode.localName!=='mixed'||htmlNode.namespaceURI!==ns||htmlAttr.name!=='mixed')throw 'same default MIME does not change HTML flag or CDATA restriction';
"#);
}
#[test]
fn template_document_owner_xml_fragment_backend_refuses_without_html_substitution(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var xml=document.implementation.createDocument(null,''),host=xml.createElementNS('http://www.w3.org/1999/xhtml','template'),content=host.content;content.appendChild(content.ownerDocument.createTextNode('held'));" );let before=(doc.nodes.len(),page.state.dom_commits);assert_eq!(page.console_eval(&mut doc,&mut forms,"host.innerHTML='<DiV/>';").errors,1);assert!(page.report().contains("XML backend"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.dom_commits),before);run(&mut doc,&mut forms,&mut page,"if(host.content!==content||content.textContent!=='held'||content.firstChild.ownerDocument!==content.ownerDocument)throw 'XML refusal changed actual contents';");assert_eq!(page.console_eval(&mut doc,&mut forms,"host.innerHTML;").errors,1);assert!(page.report().contains("XML backend"),"{}",page.report());
}

#[test]
fn template_document_owner_saved_child_factory_origin_precedes_xml_name_conversion(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var xml=document.implementation.createDocument(null,''),owner=xml.createElementNS('http://www.w3.org/1999/xhtml','template').content.ownerDocument,frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var saved=frame.contentWindow.Document.prototype.createAttribute,calls=0,name={toString:function(){calls++;return 'MiXeD';}},attr=saved.call(owner,name);if(attr.name!=='MiXeD'||attr.ownerDocument!==owner||calls!==1)throw 'actual child realm template document factory';
"#);page.set_location(&crate::navigation::address("https://other-template-owner.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.attributes.len(),page.state.dom_commits);assert_eq!(page.console_eval(&mut doc,&mut forms,"saved.call(owner,name);").errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.attributes.len(),page.state.dom_commits),before);run(&mut doc,&mut forms,&mut page,"if(calls!==1||attr.name!=='MiXeD'||owner.contentType!=='application/xml')throw 'origin before owner factory conversion';");
}
